    private static Formula ScalarObject(Formula k, Formula chi)
    {
        var scalar = new Formula.Apply(Seq(Op("Algebra"), Dot, Op("lsmul")), [k, k, k]);
        var scalarHom = Seq(Parenthesized(scalar), Dot, Op("toMonoidHom"));
        var units = new Formula.Apply(Seq(Op("Units"), Dot, Op("coeHom")), [k]);
        var characterHom = new Formula.Apply(Seq(Parenthesized(units), Dot, Op("comp")), [chi]);
        var representation = new Formula.Apply(Seq(Parenthesized(scalarHom), Dot, Op("comp")), [characterHom]);
        return new Formula.Apply(Seq(Op("FDRep"), Dot, Op("of")), [representation]);
    }
    private static Formula Op(string name) => Seq(Operatorname, Grp(F.Id(name)));
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
